// Inbox linkage rules are pure so stale-state and export behavior can be tested.
export const sourceStamp=d=>JSON.stringify([d.fields,d.invoiceDocument||null,d.source]);
export function assertContext(doc,context){if(!doc||doc.id!==context.id||sourceStamp(doc)!==context.stamp)throw Error('This invoice changed. Reopen it from the inbox before continuing.');if(['queued','rejected','approved'].includes(doc.status))throw Error('Process this invoice and keep it unapproved before changing its comparison.');}
export function invoiceFor(doc){if(!doc.invoiceDocument)throw Error('Review the invoice line items before matching.');return {...structuredClone(doc.invoiceDocument),vendor:doc.fields.vendor,number:doc.fields.number,subtotal:doc.fields.subtotal,tax:doc.fields.tax,total:doc.fields.total,due:doc.fields.due};}
export function linkComparison(doc,context,invoice,po,comparison){assertContext(doc,context);if(invoice.number!==doc.fields.number||invoice.vendor!==doc.fields.vendor||invoice.total!==doc.fields.total||invoice.tax!==doc.fields.tax)throw Error('Comparison must use the selected inbox invoice.');const old=doc.workflow;const same=old&&JSON.stringify(old.invoice)===JSON.stringify(invoice)&&JSON.stringify(old.po)===JSON.stringify(po)&&JSON.stringify(old.comparison.lineDecisions??[])===JSON.stringify(comparison.lineDecisions??[])&&JSON.stringify(old.comparison.pendingLineMatches??[])===JSON.stringify(comparison.pendingLineMatches??[]);return {...doc,workflow:same?old:{sourceStamp:context.stamp,invoice:structuredClone(invoice),po:structuredClone(po),comparison:structuredClone(comparison),state:comparison.hasDiscrepancy||comparison.pendingLineMatches?.length||comparison.taxDifferenceCents===null||comparison.differenceCents===null?'on_hold':'matched'},workflowHistory:old&&!same?[...(doc.workflowHistory||[]),old]:(doc.workflowHistory||[])};}
export function linkCase(doc,context,c){assertContext(doc,context);const w=doc.workflow;if(!w||w.sourceStamp!==context.stamp||JSON.stringify(c.original)!==JSON.stringify(w.invoice)||JSON.stringify(c.po)!==JSON.stringify(w.po))throw Error('Case no longer matches the inbox comparison. Reopen the invoice.');return {...doc,workflow:{...w,case:structuredClone(c),state:c.status==='resolved'?'resolved':c.status==='matched'?'matched':c.status==='revision_ready'?'revision_ready':'on_hold'}};}
export function workflowIssue(doc){const w=doc.workflow;if(w&&w.sourceStamp!==sourceStamp(doc))return 'Invoice changed. Recheck its purchase order before export.';if(doc.requiresPo&&!w)return 'Match this invoice with its purchase order before export.';if(w&&!['matched','resolved'].includes(w.state))return 'Purchase-order discrepancy is on hold. Verify a correction and resolve the case before export.';return null;}
export function effectiveFields(doc){const revised=doc.workflow?.state==='resolved'?doc.workflow.case?.revisions.at(-1)?.document:null;return revised?{...doc.fields,vendor:revised.vendor,number:revised.number,date:revised.date??revised.issued??doc.fields.date,due:revised.due??doc.fields.due,subtotal:revised.subtotal??revised.lines.reduce((s,l)=>s+l.quantity*l.unitPrice,0),tax:revised.tax,total:revised.total}:doc.fields;}
